///|
fn proxy(
  state : Json,
  executable : String,
  services~ : Bool = true,
  lease~ : String = "",
) -> String raise {
  let args = ["env"]
  if workspace_directory(state) is Some(directory) {
    args.push("-C")
    args.push(directory)
  }
  for name in location_variables {
    args.push("-u")
    args.push(name)
  }
  for name in location_variables {
    if field(field(state, "devsyEnv").unwrap(), name)
      is Some(Json::String(value)) {
      args.push(name + "=" + value)
    }
  }
  (args +
  [executable, "--ssh-proxy", lease] +
  saved_command(state) +
  devsy_args(state) +
  [
    "workspace",
    "ssh",
    required(state, "workspaceId"),
    "--stdio",
    "--user",
    required(state, "user"),
  ] +
  (if services { [] } else { ["--start-services=false"] }))
  .map(quote)
  .join(" ")
  .replace_all(old="%", new="%%")
}

