///|
async fn devsy_result(
  state : Json,
  args : Array[String],
  stage : String,
) -> (Int32, String, String) {
  let environment = workspace_environment(state)
  let invocation = saved_command(state)
  let logging = if devsy_progress_stage(stage) {
    ["--log-level", "debug", "--log-output", "json"]
  } else {
    []
  }
  let result = command_result(
    workspace_program(state, invocation[0]),
    invocation[1:].to_owned() + devsy_args(state) + logging + args,
    stage,
    environment~,
    cwd?=workspace_directory(state).map(path => path[:]),
  )
  result
}

///|
async fn devsy(state : Json, args : Array[String], stage : String) -> String {
  let (status, output, detail) = devsy_result(state, args, stage)
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
}

///|
fn saved_command(state : Json) -> Array[String] raise ConfigError {
  command_field(state, "recipeResult.userData").unwrap_or(["devsy"])
}

///|
fn proxy(
  state : Json,
  executable : String,
  services~ : Bool = true,
  lease~ : String = "",
) -> String raise {
  let args = ["env"]
  if workspace_directory(state) is Some(directory) {
    args.push("-C")
    args.push(directory)
  }
  for name in location_variables {
    args.push("-u")
    args.push(name)
  }
  for name in location_variables {
    if field(field(state, "devsyEnv").unwrap(), name)
      is Some(Json::String(value)) {
      args.push(name + "=" + value)
    }
  }
  (args +
  [executable, "--ssh-proxy", lease] +
  saved_command(state) +
  devsy_args(state) +
  [
    "workspace",
    "ssh",
    required(state, "workspaceId"),
    "--stdio",
    "--user",
    required(state, "user"),
  ] +
  (if services { [] } else { ["--start-services=false"] }))
  .map(quote)
  .join(" ")
  .replace_all(old="%", new="%%")
}

///|
async fn ssh_args(
  state : Json,
  services~ : Bool = true,
  lease~ : String = "",
) -> Array[String] {
  [
    "-o",
    "ProxyCommand=" + proxy(state, adapter_executable(), services~, lease~),
  ] +
  ssh_target_args(state)
}

///|
fn ssh_target_args(state : Json) -> Array[String] raise {
  [
    "-o",
    "BatchMode=yes",
    "-o",
    "ConnectTimeout=15",
    "-o",
    "StrictHostKeyChecking=no",
    "-o",
    "UserKnownHostsFile=/dev/null",
    "-o",
    "LogLevel=ERROR",
    required(state, "user") + "@" + required(state, "workspaceId") + ".devsy",
  ]
}

///|
fn ssh_mux_options(state : Json, directory : String) -> Array[String] raise {
  [
    "-o",
    "ProxyCommand=false",
    "-o",
    "ControlMaster=no",
    "-S",
    control_socket(state, directory),
  ] +
  ssh_target_args(state)
}

///|
async fn mux_ssh_args(state : Json) -> Array[String] {
  let directory = required(state, "tunnelDirectory")
  let mut waiting = false
  @async.with_timeout(connection_timeout_ms(state~), async fn() {
    while true {
      let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
      guard field(saved, "workspaceUid") == field(state, "workspaceUid") else {
        raise AdapterError("SSH master ownership changed")
      }
      let ready = try {
        check_tunnel(saved, directory)
        true
      } catch {
        _ => false
      }
      if ready {
        if waiting {
          save_diagnostic(
            "ssh-channel",
            "recovered",
            tunnel_directory=directory,
            recording=workspace_recording(state),
          )
        }
        return ssh_mux_options(saved, directory)
      }
      if !waiting {
        waiting = true
        save_diagnostic(
          "ssh-channel",
          "waiting",
          tunnel_directory=directory,
          recording=workspace_recording(state),
        )
      }
      @async.sleep(500)
    } nobreak {
      abort("unreachable")
    }
  })
}

///|
async fn remote(state : Json, script : String, stage : String) -> String {
  let args = mux_ssh_args(state)
  command(
    workspace_program(state, "ssh"),
    args + [script],
    stage,
    environment=workspace_environment(state),
    cwd?=workspace_directory(state).map(path => path[:]),
  )
}

